WITH filtered AS (SELECT *, CONCAT(event_type, '/', page) AS event_type_page FROM web_events WHERE event_time >= TIMESTAMP '2023-08-01 00:00:00' AND page IS DISTINCT FROM '/checkout') SELECT *, ROW_NUMBER() OVER (PARTITION BY MONTH(event_time) ORDER BY event_time DESC, id) AS seq_no, AVG(duration_sec) OVER w_ordered AS duration_sec_avg_3_prior, SUM(duration_sec) OVER w_ordered_2 AS duration_sec_sum_90d, SUM(duration_sec) OVER (PARTITION BY session_id, page) AS session_id_sum_duration_sec FROM filtered WINDOW w_ordered AS (PARTITION BY DATE_TRUNC('week', event_time) ORDER BY event_time, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING), w_ordered_2 AS (PARTITION BY DATE_TRUNC('WEEK', event_time), page ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW)
